<template><el-card><template #header><div class="head"><span>角色权限</span><el-button type="primary" @click="openCreate">新增角色</el-button></div></template><el-table :data="rows" v-loading="loading"><el-table-column prop="name" label="角色"/><el-table-column prop="remark" label="说明"/><el-table-column label="权限数"><template #default="s">{{ Array.isArray(s.row.perms) ? s.row.perms.length : 0 }}</template></el-table-column><el-table-column label="操作"><template #default="s"><el-button link @click="openEdit(s.row)">编辑</el-button><el-button v-if="!s.row.isSystem" link type="danger" :loading="deleting===s.row.id" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table><el-empty v-if="!loading&&!rows.length" description="暂无角色"/></el-card><el-dialog v-model="visible" :title="editing?'编辑角色':'新增角色'" width="520px" destroy-on-close><el-form label-width="78px"><el-form-item label="角色名" required><el-input v-model.trim="form.name"/></el-form-item><el-form-item label="说明"><el-input v-model.trim="form.remark"/></el-form-item><el-form-item label="权限"><el-select v-model="form.perms" multiple filterable allow-create default-first-option placeholder="输入权限码后回车" style="width:100%"><el-option v-for="item in knownPerms" :key="item" :label="item" :value="item"/></el-select><div class="hint">权限码与后端权限体系一致；可输入新权限码。</div></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog></template><script setup lang="ts">import {ref,onMounted} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import {roleApi} from '@/api';const rows=ref<any[]>([]),loading=ref(false),visible=ref(false),saving=ref(false),deleting=ref<number|undefined>(),editing=ref<any>(null);const form=ref<any>({name:'',remark:'',perms:[]});const knownPerms=['DASHBOARD','GOODS_LIST','GOODS_CREATE','GOODS_EDIT','CATEGORY_MANAGE','FREIGHT_MANAGE','ORDER_LIST','VERIFY_LOG','VERIFY_DO','MEMBER_LIST','SHOP_MANAGE','STORE_MANAGE','POINTS_MANAGE','STAFF_MANAGE','ROLE_MANAGE','MESSAGE_MANAGE'];const unwrap=(r:any)=>r?.data??r;async function load(){loading.value=true;try{const d:any=unwrap(await roleApi.list());rows.value=Array.isArray(d)?d:d?.list??d?.items??[]}catch(e:any){rows.value=[];ElMessage.error(e?.response?.data?.message||e?.message||'角色加载失败')}finally{loading.value=false}}function openCreate(){editing.value=null;form.value={name:'',remark:'',perms:[]};visible.value=true}function openEdit(r:any){editing.value=r;form.value={name:r.name||'',remark:r.remark||'',perms:Array.isArray(r.perms)?[...r.perms]:[]};visible.value=true}async function save(){if(!form.value.name)return ElMessage.warning('请输入角色名');saving.value=true;try{if(editing.value)await roleApi.update(editing.value.id,form.value);else await roleApi.create(form.value);ElMessage.success('保存成功');visible.value=false;await load()}catch(e:any){ElMessage.error(e?.response?.data?.message||e?.message||'保存失败')}finally{saving.value=false}}async function remove(r:any){try{await ElMessageBox.confirm(`确定删除角色「${r.name}」吗？`,'删除角色',{type:'warning'});deleting.value=r.id;await roleApi.remove(r.id);ElMessage.success('角色已删除');await load()}catch(e:any){if(e!=='cancel'&&e!=='close')ElMessage.error(e?.message||'删除失败')}finally{deleting.value=undefined}}onMounted(load);</script><style scoped>.head{display:flex;justify-content:space-between;align-items:center}.hint{font-size:12px;color:#909399;margin-top:6px}</style>
